import{_ as l,c as a,o as e,ae as i}from"./chunks/framework.U1Gow_7P.js";const b=JSON.parse('{"title":"📋 JUNCRAFT 管理组工作与管理规范","description":"","frontmatter":{},"headers":[],"relativePath":"optos.md","filePath":"optos.md"}'),r={name:"optos.md"};function o(n,t,s,h,d,g){return e(),a("div",null,t[0]||(t[0]=[i('<h1 id="📋-juncraft-管理组工作与管理规范" tabindex="-1">📋 JUNCRAFT 管理组工作与管理规范 <a class="header-anchor" href="#📋-juncraft-管理组工作与管理规范" aria-label="Permalink to &quot;📋 JUNCRAFT 管理组工作与管理规范&quot;">​</a></h1><blockquote><p><strong>版本：v2.2 | 生效日期：2025年7月 | 发布机构：JUNCRAFT 管理组</strong></p></blockquote><hr><h2 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h2><h3 id="第1条-制定目的" tabindex="-1">第1条 制定目的 <a class="header-anchor" href="#第1条-制定目的" aria-label="Permalink to &quot;第1条 制定目的&quot;">​</a></h3><p>为保障 JUNCRAFT 服务器的长期稳定与和谐发展，规范管理组成员的行为与权限行使，提升管理效率与服务质量，依据《JUNCRAFT 服务器管理条例》（以下简称《条例》）制定本规范。</p><h3 id="第2条-适用范围" tabindex="-1">第2条 适用范围 <a class="header-anchor" href="#第2条-适用范围" aria-label="Permalink to &quot;第2条 适用范围&quot;">​</a></h3><p>本规范适用于 JUNCRAFT 服主、超管、管理员及协管人员，涵盖其日常管理、决策、沟通、监督等各方面行为。</p><h3 id="第3条-基本原则" tabindex="-1">第3条 基本原则 <a class="header-anchor" href="#第3条-基本原则" aria-label="Permalink to &quot;第3条 基本原则&quot;">​</a></h3><p>管理组成员应秉持<strong>公平、公正、公开</strong>的原则，以服务玩家、维护服务器秩序为首要职责，严禁以权谋私、滥用职权或玩忽职守。</p><hr><h2 id="第二章-管理组架构与职责" tabindex="-1">第二章 管理组架构与职责 <a class="header-anchor" href="#第二章-管理组架构与职责" aria-label="Permalink to &quot;第二章 管理组架构与职责&quot;">​</a></h2><h3 id="第4条-管理组角色与职责" tabindex="-1">第4条 管理组角色与职责 <a class="header-anchor" href="#第4条-管理组角色与职责" aria-label="Permalink to &quot;第4条 管理组角色与职责&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">角色</th><th style="text-align:left;">职责描述</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>👑 服主</strong></td><td style="text-align:left;">服务器最高负责人，拥有最终决定权，负责重大事项裁定、管理组任命与监督、对外合作等。</td></tr><tr><td style="text-align:center;"><strong>🛡️ 超管</strong></td><td style="text-align:left;">拥有服务器后台权限，服主无法常态化管理服务器时依据服务器规则代行其权利。</td></tr><tr><td style="text-align:center;"><strong>🔰 管理员</strong></td><td style="text-align:left;">负责日常服务器运营、玩家管理、违规处理、活动组织、规则执行与反馈处理。</td></tr></tbody></table><h3 id="第5条-值班制度" tabindex="-1">第5条 值班制度 <a class="header-anchor" href="#第5条-值班制度" aria-label="Permalink to &quot;第5条 值班制度&quot;">​</a></h3><ol><li>管理员应保持稳定的在线频率，确保每日有至少 <strong>1名管理员</strong> 在岗处理日常事务。</li><li>管理组成员需在官方群组标注可联系时间，便于玩家反馈与求助。</li></ol><hr><h2 id="第三章-管理组行为规范" tabindex="-1">第三章 管理组行为规范 <a class="header-anchor" href="#第三章-管理组行为规范" aria-label="Permalink to &quot;第三章 管理组行为规范&quot;">​</a></h2><h3 id="第6条-基本行为要求" tabindex="-1">第6条 基本行为要求 <a class="header-anchor" href="#第6条-基本行为要求" aria-label="Permalink to &quot;第6条 基本行为要求&quot;">​</a></h3><ol><li>管理组成员必须以身作则，严格遵守《条例》及本规范。</li><li>禁止利用权限为自己或他人谋取不正当利益，包括但不限于： <ul><li>私自刷取/复制游戏物品</li><li>修改玩家数据或服务器后台</li><li>泄露玩家隐私信息</li><li>利用管理身份获取非正常游戏优势</li></ul></li><li>禁止在公共场合与玩家发生争吵、辱骂或情绪化发言，应保持专业与克制。</li></ol><h3 id="第7条-禁止线下现金交易" tabindex="-1">第7条 禁止线下现金交易 <a class="header-anchor" href="#第7条-禁止线下现金交易" aria-label="Permalink to &quot;第7条 禁止线下现金交易&quot;">​</a></h3><ol><li><strong>严禁管理组成员以任何形式参与或促成与玩家的线下现金交易</strong>，包括但不限于： <ul><li>出售游戏内物品、货币、权限或领地</li><li>接受玩家转账、红包、礼品卡等作为“管理关照”的回报</li><li>介绍或担保第三方与玩家进行线下交易</li></ul></li><li>违反者一经查实，<strong>立即免职并永久封禁</strong>，情节严重者将联合其他服务器进行云黑通报。</li><li>玩家如发现管理员涉及线下交易，可通过保密渠道向服主举报。</li></ol><h3 id="第8条-处罚执行规范" tabindex="-1">第8条 处罚执行规范 <a class="header-anchor" href="#第8条-处罚执行规范" aria-label="Permalink to &quot;第8条 处罚执行规范&quot;">​</a></h3><ol><li>执行处罚前应确认违规事实，收集<strong>清晰证据</strong>（截图、日志、聊天记录等）。</li><li>处罚后应在管理组内部记录，并在公告频道简要说明处罚原因与依据（涉及隐私的隐去敏感信息）。</li><li>禁止未经讨论擅自更改处罚结果，特殊情况需报服主裁定。</li></ol><h3 id="第9条-保密义务" tabindex="-1">第9条 保密义务 <a class="header-anchor" href="#第9条-保密义务" aria-label="Permalink to &quot;第9条 保密义务&quot;">​</a></h3><ol><li>管理组成员不得泄露内部讨论内容、玩家隐私信息、服务器后台数据等。</li><li>未经授权，不得对外发布服务器内部未公开的决策或信息。</li><li>违反保密义务者，视情节给予警告、暂停权限直至免职处理。</li></ol><hr><h2 id="第四章-管理组决策机制" tabindex="-1">第四章 管理组决策机制 <a class="header-anchor" href="#第四章-管理组决策机制" aria-label="Permalink to &quot;第四章 管理组决策机制&quot;">​</a></h2><h3 id="第10条-决策分类与流程" tabindex="-1">第10条 决策分类与流程 <a class="header-anchor" href="#第10条-决策分类与流程" aria-label="Permalink to &quot;第10条 决策分类与流程&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">决策类型</th><th style="text-align:left;">处理方式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>日常事务</strong></td><td style="text-align:left;">由当值管理员依据《条例》独立处理，事后可简要报备</td></tr><tr><td style="text-align:left;"><strong>重要决策</strong></td><td style="text-align:left;">管理组内部讨论 → 投票表决（赞成票 &gt; 50%） → 服主最终裁定</td></tr><tr><td style="text-align:left;"><strong>紧急事务</strong></td><td style="text-align:left;">管理员可先行处理，事后24小时内向管理组完整报备</td></tr></tbody></table><p><strong>重要决策包括但不限于</strong>：</p><ul><li>《条例》与规范修订</li><li>大型活动举办</li><li>服务器换档/版本更新</li><li>管理组人事变动（新增、免职、换届）</li><li>封禁玩家</li></ul><h3 id="第11条-投票机制" tabindex="-1">第11条 投票机制 <a class="header-anchor" href="#第11条-投票机制" aria-label="Permalink to &quot;第11条 投票机制&quot;">​</a></h3><ol><li>管理组内部投票适用于争议事项，投票周期不超过 <strong>48小时</strong>。</li><li>投票结果需记录存档，票数相同时由服主裁定。</li><li>重大决策结果（除隐私内容外）应在官方群组进行公示，接受玩家监督。</li></ol><hr><h2 id="第五章-管理组监督与考核" tabindex="-1">第五章 管理组监督与考核 <a class="header-anchor" href="#第五章-管理组监督与考核" aria-label="Permalink to &quot;第五章 管理组监督与考核&quot;">​</a></h2><h3 id="第12条-内部监督" tabindex="-1">第12条 内部监督 <a class="header-anchor" href="#第12条-内部监督" aria-label="Permalink to &quot;第12条 内部监督&quot;">​</a></h3><ol><li>管理组成员之间应相互监督，发现违规行为应及时向服主报告。</li><li>对管理员的投诉或举报，服主应在 <strong>7日内</strong> 启动调查并反馈结果。</li><li>建立管理组工作日志制度，记录每日处理事项，便于追溯与复盘。</li></ol><h3 id="第13条-玩家监督机制" tabindex="-1">第13条 玩家监督机制 <a class="header-anchor" href="#第13条-玩家监督机制" aria-label="Permalink to &quot;第13条 玩家监督机制&quot;">​</a></h3><ol><li><p><strong>季度满意度测评</strong>：</p><ul><li>每季度通过匿名问卷收集玩家对各位管理员的满意度评分（1-5分）及文字评价。</li><li>测评结果作为管理员工作评价的核心参考。</li><li>连续两季度评分低于3分者，启动评估程序（观察期/免职讨论）。</li></ul></li><li><p><strong>即时反馈渠道</strong>：</p><ul><li>玩家可通过邮箱、反馈问卷、官方群组等渠道对管理行为提出意见或举报。</li></ul></li></ol><h3 id="第14条-违规处理" tabindex="-1">第14条 违规处理 <a class="header-anchor" href="#第14条-违规处理" aria-label="Permalink to &quot;第14条 违规处理&quot;">​</a></h3><ol><li>管理员若违反本规范或《条例》，视情节轻重给予以下处理：</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">情节</th><th style="text-align:left;">处理措施</th></tr></thead><tbody><tr><td style="text-align:left;">轻微违规（如值班懈怠、语言不当）</td><td style="text-align:left;">内部警告、口头提醒</td></tr><tr><td style="text-align:left;">一般违规（如轻微滥用职权、未按规定处罚）</td><td style="text-align:left;">暂停权限 3-7 天，内部通报</td></tr><tr><td style="text-align:left;">严重违规（如线下交易、篡改数据、泄露隐私）</td><td style="text-align:left;">立即免职，永久封禁</td></tr><tr><td style="text-align:left;">态度恶劣/拒不配合/报复行为</td><td style="text-align:left;">在原处罚基础上加重处理，直至永久封禁及封禁IP</td></tr></tbody></table><ol start="2"><li>免职决定需经服主或超过 <strong>50%在职管理员</strong> 投票同意后生效。</li></ol><hr><h2 id="第六章-管理员申请与选拔流程" tabindex="-1">第六章 管理员申请与选拔流程 <a class="header-anchor" href="#第六章-管理员申请与选拔流程" aria-label="Permalink to &quot;第六章 管理员申请与选拔流程&quot;">​</a></h2><h3 id="第15条-任职基本条件" tabindex="-1">第15条 任职基本条件 <a class="header-anchor" href="#第15条-任职基本条件" aria-label="Permalink to &quot;第15条 任职基本条件&quot;">​</a></h3><ol><li><strong>游戏时长与活跃度</strong>： <ul><li>加入服务器满 <strong>30天</strong> 以上</li><li>游戏在线时长累计不少于 <strong>50小时</strong></li><li>近14天内保持活跃</li></ul></li><li><strong>信誉要求</strong>： <ul><li>无严重违规记录（S类、A类、B类）</li><li>近30天内无C类及以上处罚记录</li><li>在服务器内拥有良好声誉</li></ul></li><li><strong>能力要求</strong>： <ul><li>熟悉《服务器管理条例》及本规范</li><li>了解服务器核心玩法与常用指令</li><li>具备良好的沟通能力与情绪控制能力</li><li>有稳定的在线时间（每日不少于2小时优先）</li></ul></li></ol><h3 id="第16条-申请方式" tabindex="-1">第16条 申请方式 <a class="header-anchor" href="#第16条-申请方式" aria-label="Permalink to &quot;第16条 申请方式&quot;">​</a></h3><p>玩家可通过以下任一方式申请加入管理组：</p><table tabindex="0"><thead><tr><th style="text-align:left;">申请方式</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>📝 问卷申请</strong></td><td style="text-align:left;">填写管理员申请问卷，提交后由管理组审核</td></tr><tr><td style="text-align:left;"><strong>🗳️ 民主推荐</strong></td><td style="text-align:left;">获得 <strong>5名以上</strong> 活跃玩家联名推荐，经管理组审核后进入考察</td></tr><tr><td style="text-align:left;"><strong>🏆 特殊贡献</strong></td><td style="text-align:left;">对服务器有重大贡献者，可由管理组提名破格进入选拔流程</td></tr></tbody></table><h3 id="第17条-选拔流程" tabindex="-1">第17条 选拔流程 <a class="header-anchor" href="#第17条-选拔流程" aria-label="Permalink to &quot;第17条 选拔流程&quot;">​</a></h3><ol><li><strong>申请受理</strong>：管理组收到申请后，在 <strong>3个工作日内</strong> 完成初步资格审核。</li><li><strong>考察期（实习协管）</strong>： <ul><li>通过初审者进入为期 <strong>14天</strong> 的考察期，暂授“实习协管”身份。</li><li>考察期内由一名管理员担任导师，指导基础事务处理。</li><li>考察期结束由导师出具评价报告。</li></ul></li><li><strong>管理组评议</strong>： <ul><li>实习期满后，管理组内部进行评议投票。</li><li>需获得 <strong>超过60%</strong> 的在职管理员赞成票。</li></ul></li><li><strong>服主任命</strong>： <ul><li>通过评议者，由服主正式任命为管理员或协管。</li><li>任命结果在官方群组公示 <strong>24小时</strong> 后生效。</li></ul></li></ol><h3 id="第18条-破格与特殊任命" tabindex="-1">第18条 破格与特殊任命 <a class="header-anchor" href="#第18条-破格与特殊任命" aria-label="Permalink to &quot;第18条 破格与特殊任命&quot;">​</a></h3><ol><li>对服务器有特殊贡献者，可由服主直接提名，经管理组 <strong>半数以上同意</strong> 后破格任用。</li><li>紧急情况下（如管理组严重缺员），服主可临时任命管理员，但需在 <strong>7日内</strong> 完成管理组补票程序。</li></ol><hr><h2 id="第七章-申诉与反馈处理" tabindex="-1">第七章 申诉与反馈处理 <a class="header-anchor" href="#第七章-申诉与反馈处理" aria-label="Permalink to &quot;第七章 申诉与反馈处理&quot;">​</a></h2><h3 id="第19条-玩家申诉处理流程" tabindex="-1">第19条 玩家申诉处理流程 <a class="header-anchor" href="#第19条-玩家申诉处理流程" aria-label="Permalink to &quot;第19条 玩家申诉处理流程&quot;">​</a></h3><ol><li>玩家对处罚有异议的，应引导其按《条例》第15条流程申诉： <ul><li><strong>第一步</strong>：与执行处罚的管理员沟通</li><li><strong>第二步</strong>：若沟通无效，在收到处罚通知后 <strong>3日内</strong> 向服主提交申诉（附带证据）</li></ul></li><li>管理员应在申诉中提供相关证据，配合服主调查。</li><li>服主应在 <strong>7日内</strong> 作出最终裁定。</li><li>申诉期间原处罚继续有效，不得擅自撤销。</li></ol><h3 id="第20条-举报处理流程" tabindex="-1">第20条 举报处理流程 <a class="header-anchor" href="#第20条-举报处理流程" aria-label="Permalink to &quot;第20条 举报处理流程&quot;">​</a></h3><ol><li>玩家举报需提供确凿证据（截图、时间、行为描述等），无证据不予受理。</li><li>管理员应在 <strong>24小时内</strong> 初步回应，并在 <strong>3日内</strong> 完成核查与处理。</li><li>举报属实者可给予适当奖励（如游戏内物品、称号等）。</li><li>恶意举报者酌情给予警告或处罚。</li></ol><h3 id="第21条-举报时效" tabindex="-1">第21条 举报时效 <a class="header-anchor" href="#第21条-举报时效" aria-label="Permalink to &quot;第21条 举报时效&quot;">​</a></h3><ol><li>举报有效期为 <strong>事发后一周内</strong>，逾期或无法查证的不予受理。</li><li>涉及严重违规（如S类、A类）的举报，不受时效限制，但需提供充分证据。</li></ol><hr><h2 id="第八章-附则" tabindex="-1">第八章 附则 <a class="header-anchor" href="#第八章-附则" aria-label="Permalink to &quot;第八章 附则&quot;">​</a></h2><h3 id="第22条-规范修订" tabindex="-1">第22条 规范修订 <a class="header-anchor" href="#第22条-规范修订" aria-label="Permalink to &quot;第22条 规范修订&quot;">​</a></h3><ol><li>本规范由管理组根据服务器发展需要适时修订。</li><li>修订内容需经管理组讨论通过，并在官方群组公示满 <strong>48小时</strong> 后生效。</li><li>重大修订可发起玩家投票，赞成票超过 <strong>50%</strong> 方可采纳。</li></ol><h3 id="第23条-生效与解释" tabindex="-1">第23条 生效与解释 <a class="header-anchor" href="#第23条-生效与解释" aria-label="Permalink to &quot;第23条 生效与解释&quot;">​</a></h3><ol><li>本规范自发布之日起生效，取代此前所有版本的管理组工作规范。</li><li>本规范的最终解释权归 <strong>JUNCRAFT 管理组</strong> 所有。</li></ol><hr><h2 id="📬-反馈与举报渠道" tabindex="-1">📬 反馈与举报渠道 <a class="header-anchor" href="#📬-反馈与举报渠道" aria-label="Permalink to &quot;📬 反馈与举报渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">渠道</th><th style="text-align:left;">联系方式</th></tr></thead><tbody><tr><td style="text-align:left;">📧 邮箱</td><td style="text-align:left;"><a href="mailto:fgarea@163.com" target="_blank" rel="noreferrer">fgarea@163.com</a></td></tr><tr><td style="text-align:left;">💬 官方QQ群</td><td style="text-align:left;">837940467</td></tr><tr><td style="text-align:left;">📝 反馈问卷</td><td style="text-align:left;"><a href="https://docs.qq.com/form/page/DR1FOUE5FUmRUY0Ju" target="_blank" rel="noreferrer">点击填写</a></td></tr><tr><td style="text-align:left;">📝 管理员申请问卷</td><td style="text-align:left;">[点击填写]（需审核后开放）</td></tr><tr><td style="text-align:left;">👤 服主</td><td style="text-align:left;">通过官方群内联系</td></tr></tbody></table><hr><p><strong>JUNCRAFT 管理组</strong><br><em>让公平与乐趣同行</em></p>',74)]))}const f=l(r,[["render",o]]);export{b as __pageData,f as default};
